drop policy if exists "Guardians read published linked results" on public.schoolpro_results;
create policy "Guardians read published linked results" on public.schoolpro_results for select to authenticated using (
 status='published' and exists(select 1 from public.schoolpro_guardian_links gl where gl.student_id=schoolpro_results.student_id and gl.guardian_user_id=(select auth.uid()) and gl.status='active')
 and (
  not coalesce((select fs.block_results_when_owing from public.schoolpro_finance_settings fs where fs.school_id=schoolpro_results.school_id limit 1),false)
  or coalesce((select sum(greatest(inv.amount_due-inv.amount_paid,0)) from public.schoolpro_invoices inv where inv.student_id=schoolpro_results.student_id and inv.term=schoolpro_results.term and inv.session=schoolpro_results.session and inv.status<>'waived'),0)
     <= coalesce((select fs.allowed_outstanding from public.schoolpro_finance_settings fs where fs.school_id=schoolpro_results.school_id limit 1),0)
 ));
drop policy if exists "Guardians read linked schools" on public.schoolpro_schools;
create policy "Guardians read linked schools" on public.schoolpro_schools for select to authenticated using (exists(select 1 from public.schoolpro_guardian_links gl where gl.school_id=schoolpro_schools.id and gl.guardian_user_id=(select auth.uid()) and gl.status='active'));
drop policy if exists "Guardians read linked students" on public.schoolpro_students;
create policy "Guardians read linked students" on public.schoolpro_students for select to authenticated using (exists(select 1 from public.schoolpro_guardian_links gl where gl.student_id=schoolpro_students.id and gl.guardian_user_id=(select auth.uid()) and gl.status='active'));
drop policy if exists "Guardians read linked subjects" on public.schoolpro_subjects;
create policy "Guardians read linked subjects" on public.schoolpro_subjects for select to authenticated using (exists(select 1 from public.schoolpro_guardian_links gl where gl.school_id=schoolpro_subjects.school_id and gl.guardian_user_id=(select auth.uid()) and gl.status='active'));

