create or replace function private.handle_new_user()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  selected_product text := case coalesce(new.raw_user_meta_data->>'requested_service','explore')
    when 'datasub' then 'datasub'
    when 'reseller' then 'datasub'
    when 'api' then 'datasub'
    when 'school' then 'schoolpro'
    when 'consult' then 'consult'
    when 'host' then 'host'
    when 'engineering' then 'engineering'
    when 'print' then 'print'
    when 'fabrication' then 'fabrication'
    when 'compute' then 'compute'
    when 'academy' then 'academy'
    when 'digital_business' then 'digital_business'
    else 'corporate'
  end;
  is_owner boolean := lower(coalesce(new.email,''))='hassanisahassan12@gmail.com';
begin
  insert into public.profiles (id,email,first_name,middle_name,last_name,phone,sex,newsletter_opt_in,requested_service,role)
  values (new.id,coalesce(new.email,''),new.raw_user_meta_data->>'first_name',new.raw_user_meta_data->>'middle_name',new.raw_user_meta_data->>'last_name',new.raw_user_meta_data->>'phone',nullif(new.raw_user_meta_data->>'sex',''),coalesce((new.raw_user_meta_data->>'newsletter_opt_in')::boolean,true),new.raw_user_meta_data->>'requested_service',case when is_owner then 'super_admin'::public.user_role else 'customer'::public.user_role end);
  if is_owner or selected_product='datasub' then insert into public.datasub_wallets (user_id) values (new.id); end if;
  if is_owner then
    insert into public.customer_service_access (user_id,product,status,plan_name,activated_at)
    select new.id,product,'active',case when product='corporate' then 'IHLink Account' else 'Standard Access' end,now()
    from unnest(array['corporate','datasub','schoolpro','consult','host','engineering','business_centre','print','fabrication','compute','academy','digital_business']) as product
    on conflict (user_id,product) do update set status='active',activated_at=coalesce(public.customer_service_access.activated_at,excluded.activated_at);
    insert into public.admin_product_access (user_id,product,can_view,can_edit,can_approve)
    select new.id,product,true,true,true
    from unnest(array['corporate','datasub','schoolpro','consult','host','engineering','business_centre','print','fabrication','compute','academy','digital_business']) as product
    on conflict (user_id,product) do update set can_view=true,can_edit=true,can_approve=true;
  else
    insert into public.customer_service_access (user_id,product,status,plan_name,activated_at)
    values (new.id,selected_product,'active',case when selected_product='datasub' then 'Smart Earner' when selected_product='corporate' then 'IHLink Account' else 'Standard Access' end,now());
  end if;
  return new;
end; $$;
revoke all on function private.handle_new_user() from public,anon,authenticated;

