create or replace function public.refund_datasub_wallet(p_user uuid,p_transaction uuid,p_amount numeric,p_reference text)
returns boolean language plpgsql security definer set search_path='' as $$
declare inserted boolean;
begin
  if p_user is null or p_transaction is null or p_amount<=0 or nullif(trim(p_reference),'') is null then return false; end if;
  insert into public.wallet_ledger(user_id,transaction_id,entry_type,amount,reference)
  values(p_user,p_transaction,'refund',p_amount,trim(p_reference))
  on conflict(reference) do nothing;
  get diagnostics inserted = row_count;
  if not inserted then return true; end if;
  update public.datasub_wallets set balance=balance+p_amount,updated_at=now() where user_id=p_user;
