do $$
declare n text; pid uuid; oid uuid; uid uuid;
begin
  foreach n in array array['MTN','AIRTEL','GLO','T2'] loop
    select id into oid from public.datasub_catalog_offerings where service_type='AIRTIME' and network=n limit 1;
    if oid is null then
      insert into public.datasub_catalog_offerings(ihlink_plan_id,service_type,network,plan_type,name,validity,spec_key,base_provider_cost,smart_earner_price,reseller_price,api_price,top_seller_price,customer_enabled,markup_policy)
      values('IHL-AIRTIME-'||n,'AIRTIME',n,'VTU',n||' Airtime','Instant','AIRTIME|'||n,0,0,0,0,0,true,'{"pricing_mode":"customer_amount"}'::jsonb)
      returning id into oid;
    end if;
    for pid in select id from public.datasub_providers where code in ('cashsub','datastation','legitdataway') loop
      select id into uid from public.datasub_upstream_catalog where provider_id=pid and service_type='AIRTIME' and external_plan_id='VTU-'||n;
      if uid is null then
        insert into public.datasub_upstream_catalog(provider_id,service_type,external_plan_id,network,plan_type,name,validity,provider_cost,currency,active,raw_metadata,last_synced_at)
        values(pid,'AIRTIME','VTU-'||n,n,'VTU',n||' Airtime','Instant',0,'NGN',true,'{"amount_based":true}'::jsonb,now())
        returning id into uid;
      end if;
      insert into public.datasub_catalog_routes(offering_id,upstream_catalog_id,price_difference,route_enabled,priority)
      values(oid,uid,0,true,100) on conflict(offering_id,upstream_catalog_id) do update set route_enabled=true;
    end loop;
  end loop;
end $$;

