create or replace function public.finalize_schoolpro_enrollment(p_application uuid) returns uuid language plpgsql security definer set search_path='' as $$declare a public.schoolpro_admissions; sid uuid;begin select * into a from public.schoolpro_admissions where id=p_application for update;if a.id is null then raise exception 'Application not found';end if;if not exists(select 1 from public.schoolpro_members m where m.school_id=a.school_id and m.user_id=auth.uid() and m.role::text in('proprietor','administrator','registrar','admissions_officer')) and not exists(select 1 from public.schoolpro_schools s where s.id=a.school_id and s.owner_id=auth.uid()) then raise exception 'Not authorized';end if;if not exists(select 1 from public.schoolpro_admission_acceptances x where x.application_id=a.id) then raise exception 'Admission offer has not been accepted';end if;sid:=public.admit_schoolpro_applicant(a.id);update public.schoolpro_admissions set enrollment_status='enrolled',enrolled_at=now() where id=a.id;return sid;end$$;revoke all on function public.finalize_schoolpro_enrollment(uuid) from public,anon;grant execute on function public.finalize_schoolpro_enrollment(uuid) to authenticated;
create or replace function public.create_schoolpro_portal_invite(p_student uuid,p_email text,p_type text) returns uuid language plpgsql security definer set search_path='' as $$declare st public.schoolpro_students; iid uuid;begin select * into st from public.schoolpro_students where id=p_student;if st.id is null then raise exception 'Student not found';end if;if p_type not in('student','parent') then raise exception 'Invalid invite type';end if;if not exists(select 1 from public.schoolpro_members m where m.school_id=st.school_id and m.user_id=auth.uid() and m.role::text in('proprietor','administrator','registrar','admissions_officer')) and not exists(select 1 from public.schoolpro_schools s where s.id=st.school_id and s.owner_id=auth.uid()) then raise exception 'Not authorized';end if;insert into public.schoolpro_portal_invites(school_id,student_id,email,invite_type) values(st.school_id,st.id,lower(trim(p_email)),p_type) returning id into iid;perform public.queue_schoolpro_email(st.school_id,p_email,st.first_name||' '||st.last_name,'portal_invitation','Your SchoolPro portal invitation',jsonb_build_object('student_id',st.id,'invite_type',p_type));return iid;end$$;revoke all on function public.create_schoolpro_portal_invite(uuid,text,text) from public,anon;grant execute on function public.create_schoolpro_portal_invite(uuid,text,text) to authenticated;

create or replace function public.get_candidate_cbt(p_token uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare a public.schoolpro_candidate_cbt_attempts;t public.schoolpro_cbt_tests;qs jsonb;begin select * into a from public.schoolpro_candidate_cbt_attempts where access_token=p_token;if a.id is null then raise exception 'Invalid examination link';end if;if a.status='submitted' then raise exception 'Examination already submitted';end if;if a.expires_at is not null and now()>a.expires_at then raise exception 'Examination link expired';end if;select * into t from public.schoolpro_cbt_tests where id=a.test_id;if t.opens_at is not null and now()<t.opens_at then raise exception 'Examination has not opened';end if;if t.closes_at is not null and now()>t.closes_at then raise exception 'Examination has closed';end if;select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'question_type',q.question_type,'question_text',q.question_text,'options',q.options,'marks',q.marks) order by tq.position),'[]'::jsonb) into qs from public.schoolpro_cbt_test_questions tq join public.schoolpro_question_bank q on q.id=tq.question_id where tq.test_id=t.id;return jsonb_build_object('attempt_id',a.id,'title',t.title,'instructions',t.instructions,'duration_minutes',coalesce(a.duration_minutes,t.duration_minutes),'started_at',a.started_at,'questions',qs);end$$;
create or replace function public.save_candidate_cbt_answer(p_token uuid,p_question uuid,p_answer text) returns void language plpgsql security definer set search_path='' as $$declare a public.schoolpro_candidate_cbt_attempts;begin select * into a from public.schoolpro_candidate_cbt_attempts where access_token=p_token;if a.id is null or a.status='submitted' then raise exception 'Invalid examination attempt';end if;if a.expires_at is not null and now()>a.expires_at then raise exception 'Examination expired';end if;insert into public.schoolpro_candidate_cbt_answers(attempt_id,question_id,answer) values(a.id,p_question,p_answer) on conflict(attempt_id,question_id) do update set answer=excluded.answer;update public.schoolpro_candidate_cbt_attempts set last_saved_at=now() where id=a.id;end$$;
create or replace function public.submit_candidate_cbt(p_token uuid) returns numeric language plpgsql security definer set search_path='' as $$declare a public.schoolpro_candidate_cbt_attempts;s numeric;begin select * into a from public.schoolpro_candidate_cbt_attempts where access_token=p_token for update;if a.id is null then raise exception 'Invalid examination attempt';end if;if a.status='submitted' then return coalesce(a.score,0);end if;update public.schoolpro_candidate_cbt_answers ans set is_correct=(lower(trim(ans.answer))=lower(trim(q.correct_answer))),marks_awarded=case when lower(trim(ans.answer))=lower(trim(q.correct_answer)) then q.marks else 0 end from public.schoolpro_question_bank q where ans.attempt_id=a.id and ans.question_id=q.id and q.question_type in('objective','true_false');select coalesce(sum(marks_awarded),0) into s from public.schoolpro_candidate_cbt_answers where attempt_id=a.id;update public.schoolpro_candidate_cbt_attempts set status='submitted',submitted_at=now(),score=s,last_saved_at=now() where id=a.id;update public.schoolpro_admissions set entrance_score=s where id=a.application_id;return s;end$$;
